                    # nucleotide coords
                    start_nt = frame + aa_start*3
                    end_nt = frame + i*3 -1  # last codon before stop (nt positions)
                    if strand=='+':
                        orfs.append((start_nt+1, end_nt+1, i-aa_start, t[aa_start:i]))
                    else:
                        # positions on rc; convert to forward coords
                        L=len(s)
                        f_start = L - end_nt
                        f_end = L - start_nt
                        orfs.append((f_start, f_end, i-aa_start, t[aa_start:i]))
                aa_start=i+1
        if len(t)-aa_start>=min_aa:
            start_nt=frame+aa_start*3
            end_nt=frame+len(t)*3-1
            if strand=='-':
                L=len(s); f_start=L-end_nt; f_end=L-start_nt
                orfs.append((f_start,f_end,len(t)-aa_start,t[aa_start:]))
            else:
                orfs.append((start_nt+1,end_nt+1,len(t)-aa_start,t[aa_start:]))
    return orfs

