                    aa=t[i:j]
                    if strand=='+':
                        orfs.append((start_nt+1,end_nt+1,len(aa),aa))
                    else:
                        orfs.append((L-end_nt,L-start_nt,len(aa),aa))
                i=j
            else:
                i+=1
    return orfs

