import random, statistics
seq = "".join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
stops = {'TAA','TAG','TGA'}
comp=str.maketrans('ACGT','TGCA')
def orf_stats(s, min_aa=80):
    count=0; total=0; maxlen=0
    for strand in (s, s.translate(comp)[::-1]):
        for f in range(3):
            run=0
            for i in range(f, len(strand)-2, 3):
                if strand[i:i+3] in stops:
                    if run>=min_aa:
                        count+=1; total+=run*3
                    if run>maxlen: maxlen=run
                    run=0
                else:
                    run+=1
            if run>=min_aa:
                count+=1; total+=run*3
            if run>maxlen: maxlen=run
    return count, total, maxlen
obs=orf_stats(seq,80)
print("obs",obs)
random.seed(42)
bases=list(seq)
vals=[]
for it in range(20):
    random.shuffle(bases)
    vals.append(orf_stats(''.join(bases),80))
print("first 20 sims:", vals)
print("mean total", statistics.mean([v[1] for v in vals]))
print("fraction total >= obs", sum(v[1]>=obs[1] for v in vals)/len(vals))
